def _svg(inner, vb='0 0 120 120', cls=''):
    return f'<svg viewBox="{vb}" dir="ltr" class="{cls}" role="img" aria-hidden="true">{inner}</svg>'


def MEME(title, panels, n=0, cls=''):
    """An original two panel meme: each panel is (TOONS key or svg inner, caption). The punchline is the contrast."""
    if MODE == 'pdf':
        return ''
    ps = ''.join(f'<div class="mp"><div class="mart">{_svg(TOONS.get(a, a))}</div><div class="mcap">{TX(c)}</div></div>' for a, c in panels)
    inner = f'<div class="mt">{TX(title)}</div><div class="mps">{ps}</div>'
    return ST(n, inner, cls='meme ' + cls) if n else f'<div class="meme {cls}">{inner}</div>'


def MEMESLIDE(sid, title, panels, punch, kick=None):
    """A short breather between topics: a large meme, and one line that ties it to the material. Deck only."""
    if MODE == 'pdf':
        return
    S(sid, title, title, MEME(title, panels, 0, 'big') + BAND('dg', punch, 1), kick=kick or f'חלק {CUR[0]} · רגע של הומור', cls='memeslide')
